'use strict';
const albums=[{id:'7aJuG4TFXa2hmE4z1yxc3n',title:'HIT ME HARD AND SOFT',artist:'Billie Eilish',year:'2024',category:'01 / ALTERNATIVE POP',image:'https://image-cdn-fa.spotifycdn.com/image/ab67616d00001e0271d62ea7ea8a5be92d3c1f62',note:'从低语到浪潮，听见情绪的不同深度。'},{id:'4m2880jivSbbyEGAKfITCa',title:'Random Access Memories',artist:'Daft Punk',year:'2013',category:'02 / ELECTRONIC',image:'https://image-cdn-fa.spotifycdn.com/image/ab67616d00001e029b9b36b0e22870b9f542d937',note:'电子音乐与现场演奏，在节拍里相遇。'},{id:'1rpCHilZQkw84A3Y9czvMO',title:'Bewitched',artist:'Laufey',year:'2023',category:'03 / JAZZ POP',image:'https://image-cdn-ak.spotifycdn.com/image/ab67616d00001e0274c732f8aa0e0ccbb3d17d96',note:'爵士的温度，写进关于爱的日常。'}];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
$('#album-gallery').innerHTML=albums.map((a,i)=>`<article class="album-item"><a class="cover-link" href="https://open.spotify.com/album/${a.id}" target="_blank" rel="noopener"><img class="cover" src="${a.image}" alt="${a.artist}《${a.title}》官方专辑封面" width="400" height="400" loading="lazy" decoding="async"></a><div class="album-meta"><div><a href="https://open.spotify.com/album/${a.id}" target="_blank" rel="noopener"><h3>${a.title}</h3></a><p>${a.artist} · ${a.year}</p></div><button data-album="${i}" aria-label="在试听室打开 ${a.title}">↗</button></div></article>`).join('');
const media=matchMedia('(prefers-reduced-motion: reduce)');let reduce=media.matches;let introTimer;let scheduled=false;
const endIntro=()=>{document.body.classList.remove('intro-running');clearTimeout(introTimer)};
function updateMotion(){document.documentElement.classList.toggle('reduce-motion',reduce);document.body.classList.toggle('motion-enabled',!reduce);if(reduce)endIntro();renderScroll()}
media.addEventListener('change',e=>{reduce=e.matches;updateMotion()});
if(!reduce&&scrollY<80){document.body.classList.add('intro-running');introTimer=setTimeout(endIntro,4600)}
addEventListener('scroll',()=>{if(scrollY>80)endIntro()},{passive:true});document.addEventListener('focusin',e=>{if(e.target.closest('.cinema-copy'))endIntro()});updateMotion();
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.querySelectorAll('.reveal-lines').forEach(h=>h.classList.add('seen'));observer.unobserve(e.target)}}),{threshold:0.01});$$('section').filter(el=>el.querySelector('.reveal-lines')).forEach(el=>observer.observe(el));
function renderScroll(){scheduled=false;const range=document.documentElement.scrollHeight-innerHeight;$('#page-progress').style.transform=`scaleX(${range>0?scrollY/range:0})`;if(!reduce){const rect=$('.manifesto').getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight){$('.manifesto-rail').style.transform=`translateX(${-Math.max(0,Math.min(1,(innerHeight-rect.top)/(innerHeight+rect.height)))*120}px)`}}}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(renderScroll)}},{passive:true});addEventListener('resize',renderScroll);
$('#search-form').addEventListener('submit',e=>{e.preventDefault();const q=$('#search').value.trim();if(q)window.open('https://open.spotify.com/search/'+encodeURIComponent(q),'_blank','noopener')});
const discoveries={editorial:{label:'CURATED BY SPOTIFY',title:'从一张歌单开始。',body:'按风格、心情与场景，找到 Spotify 编辑精选的音乐。',url:'https://open.spotify.com/playlist/37i9dQZF1DX0SM0LYsmbMT',link:'在 Spotify 探索 Jazz Vibes ↗'},personal:{label:'MADE FOR YOU',title:'越听，越接近你的口味。',body:'Discover Weekly 每周一带来新发现；Release Radar 每周五更新新发行音乐。Spotify 根据聆听习惯推荐内容，新账户需要一段聆听时间。本页仅介绍功能，没有读取你的记录或生成推荐。',url:'https://support.spotify.com/us/article/find-playlists/',link:'了解「为你而作」↗'},artists:{label:'FOLLOW YOUR CURIOSITY',title:'喜欢一首歌，就走近它的世界。',body:'搜索歌名、歌手或专辑，进入艺人页面继续探索作品。你也可以关注喜欢的艺人，再从一张完整专辑听起。',url:'https://open.spotify.com/search',link:'在 Spotify 搜索音乐 ↗'}};
function selectTab(button){$$('[role=tab]').forEach(t=>{t.setAttribute('aria-selected',String(t===button));t.tabIndex=t===button?0:-1});const d=discoveries[button.dataset.tab],p=$('#discovery-panel');p.setAttribute('aria-labelledby',button.id);p.innerHTML=`<p class="eyebrow">${d.label}</p><h3>${d.title}</h3><p>${d.body}</p><a class="under-link" href="${d.url}" target="_blank" rel="noopener">${d.link}</a>`;p.classList.remove('panel-enter');void p.offsetWidth;p.classList.add('panel-enter')}
$$('[role=tab]').forEach((b,i)=>{b.addEventListener('click',()=>selectTab(b));b.addEventListener('keydown',e=>{const tabs=$$('[role=tab]');let next;if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(i+1)%tabs.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(i-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();selectTab(tabs[next])}})});
let selectedAlbum=albums[0];function loadEmbed(){const frame=document.createElement('iframe');frame.src='https://open.spotify.com/embed/album/'+selectedAlbum.id+'?utm_source=generator&theme=0';frame.title=selectedAlbum.artist+' — '+selectedAlbum.title+' Spotify 官方播放器';frame.allow='autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture';frame.allowFullscreen=true;frame.height='352';$('#embed-host').replaceChildren(frame);$('#close-embed').hidden=false;$('#embed-note').textContent='请使用 Spotify 播放器内的播放 / 暂停按钮。若播放器空白、只提供片段或无法播放，请在 Spotify 打开。';$('#embed-fallback').href='https://open.spotify.com/album/'+selectedAlbum.id}
$('#load-embed').addEventListener('click',loadEmbed);$$('[data-album]').forEach(b=>b.addEventListener('click',()=>{selectedAlbum=albums[Number(b.dataset.album)];loadEmbed();$('#listen').scrollIntoView({behavior:reduce?'instant':'smooth'});$('#close-embed').focus({preventScroll:true})}));$('#close-embed').addEventListener('click',()=>{const gate=document.createElement('div');gate.className='embed-gate';gate.innerHTML=`<span class="gate-number">A SIDE</span><h3>${selectedAlbum.title}</h3><p>${selectedAlbum.artist}</p><button class="button green" id="load-embed">加载官方播放器 <span>↗</span></button><small>将连接 Spotify，可能使用第三方 Cookie。<br>加载不会自动播放。</small>`;$('#embed-host').replaceChildren(gate);$('#close-embed').hidden=true;$('#embed-note').textContent='播放器已关闭，音频已停止。';$('#load-embed').addEventListener('click',loadEmbed);$('#load-embed').focus()});
$$('.library-step').forEach(b=>b.addEventListener('click',()=>{$$('.library-step').forEach(t=>{const active=t===b;t.classList.toggle('active',active);t.setAttribute('aria-expanded',String(active));document.getElementById(t.getAttribute('aria-controls')).hidden=!active})}));
const devices={speaker:['客厅音箱','把音乐交给支持 Spotify Connect 的音箱。'],tv:['电视','在兼容电视上的 Spotify 中登录，再从设备菜单选择它。'],computer:['另一台电脑','在另一台电脑的 Spotify 中登录同一账户，再选择它播放。']};$$('[data-device]').forEach(b=>b.addEventListener('click',()=>{$$('[data-device]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));const d=devices[b.dataset.device];$('#device-name').textContent=d[0];$('#device-description').textContent=d[1];$('.connect-demo').dataset.scene=b.dataset.device;$('.connect-target').classList.remove('panel-enter');void $('.connect-target').offsetWidth;$('.connect-target').classList.add('panel-enter');$('.connection-track').classList.remove('run');void $('.connection-track').offsetWidth;$('.connection-track').classList.add('run')}));
