if('PerformanceObserver' in window){try{new PerformanceObserver(list=>{const last=list.getEntries().at(-1);document.documentElement.dataset.lcpMs=String(Math.round(last.startTime))}).observe({type:'largest-contentful-paint',buffered:true});let shift=0;new PerformanceObserver(list=>{list.getEntries().forEach(e=>{if(!e.hadRecentInput)shift+=e.value});document.documentElement.dataset.layoutShift=shift.toFixed(4)}).observe({type:'layout-shift',buffered:true})}catch{}}
